// src/pages/SplashPage.js
import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from '../styles/SplashPage.module.css';

function SplashPage() {
  const [dotCount, setDotCount] = useState(0);
  const [fadeOut, setFadeOut] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    // Animate dots
    const dotInterval = setInterval(() => {
      setDotCount(prev => (prev + 1) % 4);
    }, 500);

    // Load for 3 seconds then fade out & redirect
    const timeout = setTimeout(() => {
      clearInterval(dotInterval);
      setFadeOut(true);

      // Redirect after fade out
      setTimeout(() => {
        navigate('/home'); // Change to your home page route
      }, 500);
    }, 3000);

    return () => {
      clearInterval(dotInterval);
      clearTimeout(timeout);
    };
  }, [navigate]);

  return (
    <div className={`${styles['loader-container']} ${fadeOut ? styles['fade-out'] : ''}`}>
      <div className={styles.logo}>🕺🏽</div>
      <h1>My Dancing Journey</h1>
      <div className={styles.spinner}></div>
      <div className={styles['loading-text']}>
        Loading<span className={styles.dots}>{'.'.repeat(dotCount)}</span>
      </div>
    </div>
  );
}

export default SplashPage;
